import time

from ute_ue.exceptions import VoiceCallCantWaitForever
from ute_ue.lteue import LteUe
from ute_ue.robot_api import aliases_registry
from ute_ue.voice_call import DefaultBaseVoiceCall

from taf.ue.android.exceptions import VoiceCallAlreadyInConference, WrongVoiceCallType


class AndroidVoiceCall(DefaultBaseVoiceCall):
    """Voice call operations for Android API"""

    def __init__(self, name, ue_id, definition, rpc_client, logger_name='ute_ue'):
        """
        :param name: name to assign for new voice call
        :param ue_id: name of UE where we start voice call at
        :param definition: description of voice call, instance of VoiceCallDefinition
        :param rpc_client: RPC client
        :param logger_name: where to put logs from this voice call
        """
        super().__init__(name, ue_id, definition, logger_name)
        if ue_id is None:
            self.ue_id = "no S/N"
        else:
            self.ue_id = ue_id
            self.voice_call_participants = []
            self.is_part_of_conference = False
            self.rpc_client = rpc_client

    @staticmethod
    def __get_voice_call_participants(call_numbers):
        """
        Get voice call participants.

        :param call_numbers: Destination phone numbers list
        :return: AndroidUe
        """
        ue_pool = aliases_registry()
        participants = []
        for ue in ue_pool:
            if isinstance(ue_pool[ue], LteUe) and getattr(ue_pool[ue], 'phone_number', None) in call_numbers:
                participants.append(ue_pool[ue])
        return participants

    def await_voice_call_finish(self):
        """
        Waits until ongoing voice call is finished.
        """
        self.logger.debug(f"Await for voice call {self.name} finish started")
        if self.definition.duration == 863913600.0:
            raise VoiceCallCantWaitForever(f"Voice call - {self.name} time duration set to forever!")
        else:
            self.logger.debug(f"Voice call - {self.name} time duration set to {self.definition.duration}")
            time.sleep(self.definition.duration)

    def _start_call_on_ue(self, destination_number):
        """
        Perform start voice call on UE PC.

        :param destination_number: Destination phone number or autoresponder number
        :return: None
        """
        participants = self.__get_voice_call_participants(call_numbers=[destination_number])
        if participants:
            for participant in participants:
                self.voice_call_participants.append(participant)
            self.logger.debug(f"Start voice call on UE {self.hosting_ue_name} "
                              f"to {self.voice_call_participants[0].ue_id} started")
            self.rpc_client.start_voice_call(ue_id=self.hosting_ue_name,
                                             other_ue_id=self.voice_call_participants[0].ue_id,
                                             voice_call_id=self.name,
                                             timeout_to_answer=60,
                                             with_video=self.definition.with_video)
        else:
            # Call destination might be auto responder
            self.logger.warning(f"Phone number: {destination_number} is not recognized!")
            self.rpc_client.start_voice_call(ue_id=self.hosting_ue_name,
                                             other_ue_id="",
                                             voice_call_id=self.name,
                                             autoresponder_nr=destination_number,
                                             timeout_to_answer=60,
                                             with_video=self.definition.with_video)

    def _end_call_on_ue(self, timeout=None):
        """
        Finish specific voice call on given UE.

        :param timeout: specified time to end the call
        :return:
        """
        if self.is_part_of_conference:
            _aliases_registry = aliases_registry()
            for alias in _aliases_registry:
                if "VoiceCall" in _aliases_registry[alias].__class__.__name__ \
                        and _aliases_registry[alias].is_part_of_conference:
                    _aliases_registry[alias]._called_await_or_stop = True
        self.rpc_client.stop_voice_call(ue_id=self.ue_id,
                                        voice_call_id=self.name)
        self.call_not_finish = False

    def _merge_into_conference(self, other_call):
        """
        Make a conference with other call.
        Makes several checks if it is possible to start conference call.
        To make a conference both voice call have to be on same UE.
        :param other_call: AndroidVoiceCall
        """
        if not isinstance(other_call, self.__class__):
            raise WrongVoiceCallType("Can not make conference. Second call needs to be an instance of"
                                     f" class AndroidVoiceCall, given type: {type(other_call)}")
        if self.is_part_of_conference or other_call.is_part_of_conference:
            raise VoiceCallAlreadyInConference("Can not make conference."
                                               " One of the calls is taking part in other conference!")
        self.logger.debug(f"Merge voice call {self.name} on UE {self.hosting_ue_name} started")
        self.rpc_client.merge_voice_call(ue_id=self.hosting_ue_name,
                                         voice_call_id_1=self.name,
                                         voice_call_id_2=other_call.name,
                                         call_number=other_call.definition.to)
        self.is_part_of_conference = True
        other_call.is_part_of_conference = True

    def hold(self):
        """
        Hold active voice call
        :return:
        """
        self.logger.debug(f'Holding voice call {self.name} on UE {self.ue_id}.')
        ue = self._get_incoming_call_phone_object()
        ue.hold_voice_call(name=self.name)
        self.logger.debug(f'Voice call {self.name} on UE {self.ue_id} has been held.')

    def retrieve(self):
        """
        Retrieve held voice call
        :return:
        """
        self.logger.debug(f'Retrieving voice call {self.name} on UE {self.ue_id}.')
        ue = self._get_incoming_call_phone_object()
        ue.retrieve_voice_call(name=self.name)
        self.logger.debug(f'Voice call {self.name} on UE {self.ue_id} has been retrieved.')

    def answer(self, with_video=False):
        """
        Perform answer incoming voice call on UE PC.
        :type with_video:
        :return:
        """
        # TODO: Check if there is no vc already activated?
        self.logger.debug(f"Answer voice call {self.name} on UE {self.hosting_ue_name} started")
        self.rpc_client.answer_voice_call(ue_id=self.hosting_ue_name,
                                          voice_call_id=self.name,
                                          with_video=with_video)

    def drop(self):
        """
        Drop incoming voice call
        :return:
        """
        self.logger.debug(f"Drop voice call {self.name} on UE {self.hosting_ue_name} started")
        self.rpc_client.drop_voice_call(ue_id=self.ue_id, voice_call_id=self.name)

    def _get_incoming_call_phone_object(self):
        """
        Get incoming voice call object.

        :return: UE object
        """
        ue_pool = aliases_registry()
        for ue in ue_pool:
            if isinstance(ue_pool[ue], LteUe) and ue_pool[ue].ue_id == self.ue_id:
                return ue_pool[ue]
        self.logger.warning(f"There is no UE registered in aliases registry for incoming voice call: {self.name}")
        return None

    def get_state(self):
        """
        Returns voice_call actual state.
        :return str: voice_call state
        """
        self.logger.debug(f"Get voice call {self.name} state on UE {self.ue_id} started")
        return self.rpc_client.get_voice_call_state(ue_id=self.ue_id,
                                                    voice_call_id=self.name)

    def upgrade(self):
        """
       Upgrades to video call
       :return:
        """
        self.logger.debug(f"Upgrading voice call: {self.name} to video call.")
        return self.rpc_client.upgrade_voice_call(voice_call_id=self.name)

    def downgrade(self):
        """
       Downgrades from video call
       :return:
        """
        self.logger.debug(f"Downgrading voice call: {self.name} from video call.")
        return self.rpc_client.downgrade_voice_call(voice_call_id=self.name)

    def send_dtmf(self, tones, tone_duration):
        """
        Sends DTMF tones through voice channel.
        :param tones:
        :param tone_duration:
        :return:
        """
        self.logger.debug(f"Send dtmf tones: {tones} for {tone_duration}.")
        self.rpc_client.play_dtmf_tone(ue_id=self.ue_id, voice_call_id=self.name,
                                       tones=tones, duration=tone_duration)
